class ValueStoreLossyCacheTest {

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 5, 17, 1 << 30 })
	void lookupSurvivesEvictionRollbackAndReopen(int capacity, @TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = config(capacity);
		List<Value> values = new ArrayList<>();
		for (int i = 0; i < 20; i++) {
			Value iri = Values.iri("http://cache.example/namespace-" + i + "/value");
			values.add(iri);
			values.add(Values.bnode("cache-bnode-" + i));
			values.add(Values.literal("stored literal ".repeat(5) + i, Values.iri("urn:cache:datatype:" + i)));
			values.add(Values.tripleTerm(Values.bnode("cache-subject-" + i), Values.iri("urn:cache:predicate"),
					Values.tripleTerm(Values.bnode("cache-inner-" + i), Values.iri("urn:cache:inner"), iri)));
		}
		Value[] batch = values.toArray(Value[]::new);
		long[] ids = new long[batch.length];
		File valuesDir = new File(dataDir, "values");
		Value aborted = Values.iri("http://aborted.example/namespace/value");
		ValueStore store = new ValueStore(valuesDir, config);
		try {
			store.startTransaction(true);
			store.setReplayDecision(new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false, 0, 0, 0)
					.forNativeCheckpoints());
			store.storeValues(batch, ids, batch.length);
			for (int i = 0; i < batch.length; i++) {
				assertEquals(ids[i], store.getId(batch[i]));
				assertEquals(ids[i], store.storeValue(batch[i]));
			}
			store.commit();
			assertValues(store, batch, ids);
			store.startTransaction(true);
			long abortedId = store.storeValue(aborted);
			assertEquals(aborted, store.getValue(abortedId));
			store.rollback();
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(aborted));
			assertValues(store, batch, ids);
			store.startTransaction(true);
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(aborted));
			long committedId = store.storeValue(aborted);
			assertNotEquals(LmdbValue.UNKNOWN_ID, committedId);
			assertEquals(committedId, store.getId(aborted));
			store.commit();
		} finally {
			store.close();
		}
		ValueStore reopened = new ValueStore(valuesDir, config);
		try {
			assertValues(reopened, batch, ids);
			assertEquals(aborted, reopened.getValue(reopened.getId(aborted)));
		} finally {
			reopened.close();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 5 })
	void mutatedValueDoesNotReuseMemoizedId(int capacity, @TempDir File dataDir) throws Exception {
		ValueStore store = new ValueStore(new File(dataDir, "values"), config(capacity));
		try {
			LmdbIRI mutable = store.createIRI("http://cache.example/Aa");
			int originalHash = mutable.hashCode();
			store.startTransaction(true);
			long originalId = store.storeValue(mutable);
			mutable.setNamespaceAndIri("http://cache.example/", "BB");
			assertEquals(originalHash, mutable.hashCode(), "The mutated key must still hit its original cache set");
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(mutable));
			long replacementId = store.storeValue(mutable);
			assertNotEquals(originalId, replacementId);
			assertEquals(Values.iri("http://cache.example/Aa"), store.getValue(originalId));
			assertEquals(Values.iri("http://cache.example/BB"), store.getValue(replacementId));
			store.commit();
		} finally {
			store.close();
		}
	}

	@ParameterizedTest
	@CsvSource({ "0,false", "0,true", "1,false", "1,true", "5,false", "5,true" })
	void mutatedRetainedKeyCannotUseEqualValuesCachedId(int capacity, boolean bulkLookup,
			@TempDir File dataDir) throws Exception {
		ValueStore store = new ValueStore(new File(dataDir, "values"), config(capacity));
		try {
			LmdbIRI first = store.createIRI("http://cache.example/Aa");
			LmdbIRI equal = store.createIRI("http://cache.example/Aa");
			int originalHash = first.hashCode();
			store.startTransaction(true);
			store.setReplayDecision(new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false, 0, 0, 0)
					.forNativeCheckpoints());
			long[] duplicateIds = new long[2];
			store.storeValues(new Value[] { first, equal }, duplicateIds, 2);
			assertEquals(duplicateIds[0], duplicateIds[1]);
			first.setNamespaceAndIri("http://cache.example/", "BB");
			assertEquals(originalHash, first.hashCode(), "Mutation must preserve the retained key's hash");
			long replacementId;
			if (bulkLookup) {
				long[] replacementIds = new long[1];
				store.storeValues(new Value[] { first }, replacementIds, 1);
				replacementId = replacementIds[0];
			} else {
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(first));
				replacementId = store.storeValue(first);
			}
			assertNotEquals(duplicateIds[0], replacementId, "A different lexical value needs its own dictionary ID");
			assertEquals(Values.iri("http://cache.example/Aa"), store.getValue(duplicateIds[0]));
			assertEquals(Values.iri("http://cache.example/BB"), store.getValue(replacementId));
			assertEquals(duplicateIds[0], store.getId(equal));
			store.commit();
		} finally {
			store.close();
		}
	}

	@ParameterizedTest
	@CsvSource({ "0,false", "0,true", "1,false", "1,true", "5,false", "5,true" })
	void mutatedDatatypeCannotReuseDuplicateLiteralOrNestedTermId(int capacity, boolean nested,
			@TempDir File dataDir) throws Exception {
		ValueStore store = new ValueStore(new File(dataDir, "values"), config(capacity));
		try {
			String label = "mutable datatype literal ".repeat(5);
			LmdbIRI datatype = store.createIRI("http://cache.example/Aa");
			Value firstLiteral = store.createLiteral(label, datatype);
			Value equalLiteral = store.createLiteral(label, store.createIRI("http://cache.example/Aa"));
			store.startTransaction(true);
			store.setReplayDecision(new TxnReplayPolicy.Decision(new TxnReplayPolicy(), true, false, 0, 0, 0)
					.forNativeCheckpoints());
			long[] duplicateIds = new long[2];
			store.storeValues(new Value[] { firstLiteral, equalLiteral }, duplicateIds, 2);
			assertEquals(duplicateIds[0], duplicateIds[1]);
			Value first = nested ? nestedValue(store, firstLiteral) : firstLiteral;
			Value equal = nested ? nestedValue(store, equalLiteral) : equalLiteral;
			store.storeValues(new Value[] { first, equal }, duplicateIds, 2);
			assertEquals(duplicateIds[0], duplicateIds[1]);
			int originalHash = first.hashCode();
			datatype.setNamespaceAndIri("http://cache.example/", "BB");
			assertEquals(originalHash, first.hashCode(), "A nested mutation must preserve the cache-key hash");
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(first));
			long[] replacementIds = new long[1];
			store.storeValues(new Value[] { first }, replacementIds, 1);
			assertNotEquals(duplicateIds[0], replacementIds[0]);
			Value original = Values.literal(label, Values.iri("http://cache.example/Aa"));
			Value replacement = Values.literal(label, Values.iri("http://cache.example/BB"));
			assertEquals(nested ? nestedExpected(original) : original, store.getValue(duplicateIds[0]));
			assertEquals(nested ? nestedExpected(replacement) : replacement, store.getValue(replacementIds[0]));
			assertEquals(duplicateIds[0], store.getId(equal));
			store.commit();
		} finally {
			store.close();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 5 })
	void clearInvalidatesNamespaceAndIdMappings(int capacity, @TempDir File dataDir) throws Exception {
		File valuesDir = new File(dataDir, "values");
		Value original = Values.iri("http://cache.example/namespace/original");
		Value replacement = Values.iri("http://cache.example/namespace/replacement");
		long replacementId;
		ValueStore store = new ValueStore(valuesDir, config(capacity));
		try {
			store.startTransaction(true);
			long originalId = store.storeValue(original);
			store.commit();
			assertEquals(original, store.getValue(originalId));
			store.clear();
			store.startTransaction(true);
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(original));
			replacementId = store.storeValue(replacement);
			store.commit();
			assertNotEquals(originalId, replacementId, "A cleared live dictionary must allocate a fresh ID");
			assertEquals(replacement, store.getValue(replacementId));
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(original));
		} finally {
			store.close();
		}
		ValueStore reopened = new ValueStore(valuesDir, config(capacity));
		try {
			assertEquals(replacement, reopened.getValue(replacementId), "The namespace must be recreated on disk");
			assertEquals(LmdbValue.UNKNOWN_ID, reopened.getId(original));
		} finally {
			reopened.close();
		}
	}

	private static LmdbStoreConfig config(int capacity) {
		return new LmdbStoreConfig().setValueIDCacheSize(capacity)
				.setNamespaceCacheSize(capacity)
				.setNamespaceIDCacheSize(capacity)
				.setValueCacheSize(1)
				.setInlineLiterals(false);
	}

	private static Value nestedValue(ValueStore store, Value value) {
		return store.createTripleTerm(store.createBNode("cache-outer"), store.createIRI("urn:cache:outer"),
				store.createTripleTerm(store.createBNode("cache-inner"), store.createIRI("urn:cache:inner"), value));
	}

	private static Value nestedExpected(Value value) {
		return Values.tripleTerm(Values.bnode("cache-outer"), Values.iri("urn:cache:outer"),
				Values.tripleTerm(Values.bnode("cache-inner"), Values.iri("urn:cache:inner"), value));
	}

	private static void assertValues(ValueStore store, Value[] values, long[] ids) throws Exception {
		for (int i = 0; i < values.length; i++) {
			assertEquals(ids[i], store.getId(values[i]));
			assertEquals(values[i], store.getValue(ids[i]));
		}
	}
}
